WITH flattened AS (SELECT id, plan, effective_from, currency, EXPLODE_OUTER(tier_limits) AS tier_value FROM price_tiers), valid AS (SELECT *, SUBSTRING(plan, 1, 3) AS plan_prefix FROM flattened WHERE effective_from > TO_DATE('2024-04-07')), cleaned AS (SELECT plan, effective_from, plan_prefix, COALESCE(tier_value, 0) AS tier_value_filled FROM valid WHERE effective_from BETWEEN '2023-08-17' AND '2024-04-17'), remaining_keys AS (SELECT plan FROM cleaned INTERSECT ALL SELECT plan FROM price_tiers WHERE currency = 'EUR'), reconciled AS (SELECT s.* FROM cleaned s INNER JOIN remaining_keys k ON s.plan = k.plan), base AS (SELECT *, DATE_TRUNC('MONTH', effective_from) AS effective_from_period FROM reconciled WHERE effective_from >= TO_DATE('2024-05-13')) SELECT CASE WHEN tier_value_filled >= 77 THEN 'HIGH' ELSE 'LOW' END AS tier_value_filled_tier, DATE_TRUNC('QUARTER', effective_from_period) AS quarter_start, COUNT(CASE WHEN plan = 'pro' THEN 1 END) AS pro_count, COUNT_IF(plan = 'enterprise') AS enterprise_events, GROUPING(CASE WHEN tier_value_filled >= 77 THEN 'HIGH' ELSE 'LOW' END) AS grouping_level FROM base GROUP BY CUBE (CASE WHEN tier_value_filled >= 77 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('QUARTER', effective_from_period)) HAVING enterprise_events >= 1 ORDER BY tier_value_filled_tier DESC;
